SELECT COALESCE(SUM(payment_amount) FILTER (WHERE payment_method IN ('***', '***')), 0) AS cash_payment_amount
FROM agent_v3_payment_refund_view
WHERE agent_v3_payment_refund_view.store_id = ANY(:allowedStoreIds) AND agent_v3_payment_refund_view.paid_at >= :startAt AND agent_v3_payment_refund_view.paid_at < :endAt AND (payment_method IN ('***', '***')) LIMIT 1;
